    override fun read(buf: ByteBuffer): RblueException {


        return when(buf.getInt()) {
            1 -> RblueException.Unsupported(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> RblueException.Permission(
                FfiConverterTypePermissionReason.read(buf),
                )
            3 -> RblueException.NotFound(
                FfiConverterString.read(buf),
