                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RblueException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RblueException.Pairing -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypePairingStatus.allocationSize(value.`status`)
            )
            is RblueException.Att -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUByte.allocationSize(value.`code`)
                + FfiConverterOptionalUShort.allocationSize(value.`handle`)
            )
            is RblueException.Platform -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterInt.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is RblueException.InvalidLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`len`)
                + FfiConverterULong.allocationSize(value.`max`)
            )
            is RblueException.Disconnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RblueException.InvalidState -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is RblueException.Backend -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is RblueException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
