/**
 * Host-side receiver for adapter events and GATT notifications.
 *
 * Implemented on the foreign side (Kotlin object / Swift class) and
 * registered with [`Rblue::set_event_sink`]. Methods are invoked from the
 * facade's pump worker threads: implementations must not block, must not
 * re-enter the facade, and must not throw - an exception unwinds into the
 * pump and terminates event delivery. Buffering and drop accounting are the
 * binding layer's job (`callbackFlow(BUFFERED)` / `AsyncStream`; see the
 * crate documentation).
 */
public interface EventSink {

    /**
     * One adapter event (a serialized `rblue_api::AdapterEvent`): state
     * changes, discoveries, connection state. Values are opaque - parse the
     * JSON with the schema the `rblue-api` serde types define.
     */
    fun `onEvent`(`eventJson`: kotlin.String)

    /**
     * One GATT notification/indication (a serialized
     * `rblue_api::Notification`), delivered only for subscribed
     * characteristics.
     */
    fun `onNotification`(`notificationJson`: kotlin.String)

    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceEventSink {
    internal object `onEvent`: UniffiCallbackInterfaceEventSinkMethod0 {
        override fun callback(`uniffiHandle`: Long,`eventJson`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeEventSink.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onEvent`(
                    FfiConverterString.lift(`eventJson`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `onNotification`: UniffiCallbackInterfaceEventSinkMethod1 {
        override fun callback(`uniffiHandle`: Long,`notificationJson`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeEventSink.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onNotification`(
                    FfiConverterString.lift(`notificationJson`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeEventSink.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeEventSink.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceEventSink.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `onEvent`,
        `onNotification`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_rblue_ffi_fn_init_callback_vtable_eventsink(vtable)
    }
}

